103	    private static void expectThrows(
104	        Class<? extends Throwable> expectedType,
105	        ThrowingRunnable action,
106	        String description
107	    ) {
108	        try {
109	            action.run();
110	        } catch (Throwable thrown) {
111	            if (expectedType.isInstance(thrown)) {
112	                return;
113	            }
114	            throw new AssertionError(
115	                description + " threw " + thrown.getClass().getSimpleName()
116	                    + " instead of " + expectedType.getSimpleName(),
117	                thrown
118	            );
119	        }
120	
121	        throw new AssertionError(description + " did not throw " + expectedType.getSimpleName());
122	    }
